<template><section class="demo-identity"><div><span class="demo-data-badge">Demo identity</span><strong>Preview as</strong><p>This changes fictional workflow visibility only. Your signed-in Cognito identity is unchanged.</p></div><select :value="workflow.identityId" aria-label="Demo preview identity" @change="changeIdentity"><option v-for="item in identities" :key="item.id" :value="item.id">{{ item.name }}</option></select><button type="button" @click="reset">Reset demo workflow</button></section></template>
<script>import { DEMO_IDENTITIES, demoWorkflow, resetDemoWorkflow, setDemoIdentity } from '../applicationAdminData.js'; import { resetAvailabilityDemo } from '../inductionAvailabilityData.js'; export default { name: 'DemoIdentitySwitcher', emits: ['reset'], data: () => ({ workflow: demoWorkflow, identities: DEMO_IDENTITIES }), methods: { changeIdentity(event) { setDemoIdentity(event.target.value); }, reset() { if (window.confirm('Reset all fictional claims, drafts, reviews, bookings and decisions?')) { resetDemoWorkflow(); resetAvailabilityDemo(); this.$emit('reset'); } } } };</script>
